<?php
declare(strict_types=1);
function pos_sale_number(): string {return 'POS-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(4)));}
function pos_products(int $seller,string $q='',int $limit=50): array {$where="p.seller_user_id=? AND p.sale_mode='fixed' AND p.status='published'";$p=[$seller];if(trim($q)!==''){$where.=' AND (p.title LIKE ? OR p.short_description LIKE ? OR EXISTS(SELECT 1 FROM product_variants pv WHERE pv.product_id=p.id AND pv.status=1 AND (pv.sku=? OR pv.barcode=? OR pv.sku LIKE ? OR pv.barcode LIKE ?)))';$term=trim($q);$like='%'.$term.'%';$p[]=$like;$p[]=$like;$p[]=$term;$p[]=$term;$p[]=$like;$p[]=$like;}try{$st=db()->prepare("SELECT p.id,p.title,p.slug,p.price,p.stock,p.image_url,p.product_type,(SELECT pv.sku FROM product_variants pv WHERE pv.product_id=p.id AND pv.status=1 AND pv.sku IS NOT NULL LIMIT 1) sku,(SELECT pv.barcode FROM product_variants pv WHERE pv.product_id=p.id AND pv.status=1 AND pv.barcode IS NOT NULL LIMIT 1) barcode FROM store_products p WHERE {$where} ORDER BY p.title LIMIT ".max(1,min(100,$limit)));$st->execute($p);return $st->fetchAll();}catch(Throwable $e){return [];}}
function pos_open_shift(int $seller,int $staff,float $cash=0): int {$q=db()->prepare("SELECT id FROM pos_shifts WHERE seller_user_id=? AND opened_by=? AND status='open' ORDER BY id DESC LIMIT 1");$q->execute([$seller,$staff]);$id=$q->fetchColumn();if($id)return (int)$id;db()->prepare("INSERT INTO pos_shifts(seller_user_id,opened_by,opening_cash,status,opened_at) VALUES(?,?,?,'open',NOW())")->execute([$seller,$staff,max(0,$cash)]);return (int)db()->lastInsertId();}

function pos_close_shift(int $seller,int $staff,float $closingCash): bool {try{$q=db()->prepare("UPDATE pos_shifts SET closing_cash=?,status='closed',closed_by=?,closed_at=NOW() WHERE seller_user_id=? AND opened_by=? AND status='open' ORDER BY id DESC LIMIT 1");$q->execute([max(0,$closingCash),$staff,$seller,$staff]);return $q->rowCount()>0;}catch(Throwable $e){return false;}}
function pos_receipt_profile(int $seller): array {try{$q=db()->prepare("SELECT * FROM pos_receipt_profiles WHERE seller_user_id=? LIMIT 1");$q->execute([$seller]);return $q->fetch()?:['seller_user_id'=>$seller,'business_name'=>'','footer_text'=>setting('pos_receipt_footer','Thank you.'),'show_qr'=>1,'show_barcode'=>1,'paper_width'=>'80mm'];}catch(Throwable $e){return ['seller_user_id'=>$seller,'business_name'=>'','footer_text'=>setting('pos_receipt_footer','Thank you.'),'show_qr'=>1,'show_barcode'=>1,'paper_width'=>'80mm'];}}
function pos_save_receipt_profile(int $seller,array $data): void {db()->prepare("INSERT INTO pos_receipt_profiles(seller_user_id,business_name,footer_text,show_qr,show_barcode,paper_width) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE business_name=VALUES(business_name),footer_text=VALUES(footer_text),show_qr=VALUES(show_qr),show_barcode=VALUES(show_barcode),paper_width=VALUES(paper_width)")->execute([$seller,trim((string)($data['business_name']??''))?:null,trim((string)($data['footer_text']??''))?:null,!empty($data['show_qr'])?1:0,!empty($data['show_barcode'])?1:0,in_array(($data['paper_width']??'80mm'),['58mm','80mm','a4'],true)?$data['paper_width']:'80mm']);}
function pos_current_shift(int $seller,int $staff): ?array {try{$q=db()->prepare("SELECT * FROM pos_shifts WHERE seller_user_id=? AND opened_by=? AND status='open' ORDER BY id DESC LIMIT 1");$q->execute([$seller,$staff]);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function pos_create_sale(array $ctx,array $items,array $customer,string $method='cash',float $discount=0,string $notes=''): array {
    if(!setting_bool('seller_pos_enabled',true))throw new RuntimeException('Seller POS is disabled.');$seller=(int)$ctx['owner_id'];$staff=(int)$ctx['user']['id'];$method=in_array($method,['cash','bank','card','wallet','other'],true)?$method:'cash';if(!$items)throw new RuntimeException('Add at least one product.');$shift=pos_current_shift($seller,$staff);if(!$shift)$shift=['id'=>pos_open_shift($seller,$staff,0)];$locked=[];$subtotal=0;db()->beginTransaction();try{foreach($items as $item){$pid=(int)($item['product_id']??0);$qty=max(1,min(999,(int)($item['quantity']??1)));$q=db()->prepare("SELECT id,title,price,stock,status,seller_user_id,sale_mode FROM store_products WHERE id=? FOR UPDATE");$q->execute([$pid]);$p=$q->fetch();if(!$p||(int)$p['seller_user_id']!==$seller||$p['status']!=='published'||$p['sale_mode']!=='fixed')throw new RuntimeException('One selected product is unavailable.');if((int)$p['stock']<$qty)throw new RuntimeException($p['title'].' does not have enough stock.');$line=(float)$p['price']*$qty;$subtotal+=$line;$locked[]=['p'=>$p,'qty'=>$qty,'line'=>$line];}$discount=max(0,min($subtotal,$discount));$total=$subtotal-$discount;$number=pos_sale_number();db()->prepare("INSERT INTO pos_sales(sale_number,seller_user_id,staff_user_id,shift_id,customer_name,customer_phone,subtotal,discount_amount,total_amount,payment_method,status,notes) VALUES(?,?,?,?,?,?,?,?,?,?,'completed',?)")->execute([$number,$seller,$staff,(int)$shift['id'],trim((string)($customer['name']??''))?:null,trim((string)($customer['phone']??''))?:null,$subtotal,$discount,$total,$method,trim($notes)?:null]);$saleId=(int)db()->lastInsertId();$iq=db()->prepare('INSERT INTO pos_sale_items(sale_id,product_id,title,quantity,unit_price,line_total) VALUES(?,?,?,?,?,?)');foreach($locked as $r){$p=$r['p'];$iq->execute([$saleId,$p['id'],$p['title'],$r['qty'],$p['price'],$r['line']]);db()->prepare("UPDATE store_products SET stock=stock-?,status=IF(stock-?<=0,'soldout',status) WHERE id=?")->execute([$r['qty'],$r['qty'],$p['id']]);if(function_exists('inventory_log_only'))inventory_log_only($seller,(int)$p['id'],-(int)$r['qty'],'sale','pos_sale',$saleId,'Sold via Seller POS',$staff);}db()->commit();try{if(function_exists('operations_audit'))operations_audit('pos.sale','pos_sale',$saleId,null,['number'=>$number,'total'=>$total],$staff);if(function_exists('accounting_post_journal')&&$total>0){accounting_post_journal('POS sale '.$number,[['account_id'=>accounting_account_id('seller_pos_clearing'),'debit'=>$total,'user_id'=>$seller,'memo'=>'Seller POS collection'],['account_id'=>accounting_account_id('pos_sales_revenue'),'credit'=>$total,'user_id'=>$seller,'memo'=>'Seller POS gross sale']],'pos_sale',$saleId,$staff);}}catch(Throwable $e){runtime_log('POS accounting/audit skipped',$e);}return ['id'=>$saleId,'sale_number'=>$number,'subtotal'=>$subtotal,'discount'=>$discount,'total'=>$total];}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function pos_sales(int $seller,int $limit=50): array {try{$q=db()->prepare('SELECT s.*,u.name staff_name FROM pos_sales s JOIN users u ON u.id=s.staff_user_id WHERE s.seller_user_id=? ORDER BY s.id DESC LIMIT '.max(1,min(200,$limit)));$q->execute([$seller]);return $q->fetchAll();}catch(Throwable $e){return [];}}
function pos_dashboard_stats(): array {try{return db()->query("SELECT COUNT(*) sales,COALESCE(SUM(total_amount),0) revenue,(SELECT COUNT(*) FROM pos_shifts WHERE status='open') open_shifts,(SELECT COUNT(DISTINCT seller_user_id) FROM pos_sales) sellers FROM pos_sales WHERE status='completed'")->fetch()?:[];}catch(Throwable $e){return [];}}
